// Set the flags option of pl.create in a new session; a bad entry throws an Error that names the flag
function set_session_flags( session, flags ) {
	if( flags === undefined || flags === null )
		return;
	if( typeof flags !== "object" || Array.isArray( flags ) )
		throw new Error( "The flags option must be an object that maps flag names to values" );
	for( var name in flags ) {
		if( !Object.prototype.hasOwnProperty.call( flags, name ) )
			continue;
		var flag = new Term( name, [] );
		if( !pl.type.is_flag( flag ) )
			throw new Error( "Unknown Prolog flag: " + name );
		if( !pl.type.is_modifiable_flag( flag ) )
			throw new Error( "Prolog flag " + name + " cannot be modified" );
		var value = typeof flags[name] === "string" ? new Term( flags[name], [] ) : null;
		if( value === null || !pl.type.is_value_flag( flag, value ) )
			throw new Error( "Invalid value for Prolog flag " + name );
		session.flag[name] = value;
	}
}

function Session( options ) {
	options = typeof options === "object" && options !== null ? options : { limit: options };
	var limit = options.limit;
	limit = typeof limit === "number" && limit > 0 ? limit : null;

var pl;
(function( pl ) {

	var name = "pairs";

	// The K-V terms of a proper list, or null after an error has been raised
	var read_pairs = function( thread, atom, list ) {
		var pairs = [], pointer = list;
		while( pl.type.is_term( pointer ) && pointer.indicator === "./2" ) {
			var pair = pointer.args[0];
			if( pl.type.is_variable( pair ) ) {
				thread.throw_error( pl.error.instantiation( atom.indicator ) );
				return null;
			} else if( !pl.type.is_term( pair ) || pair.indicator !== "-/2" ) {
				thread.throw_error( pl.error.type( "pair", pair, atom.indicator ) );
				return null;
			}
			pairs.push( pair );
			pointer = pointer.args[1];
		}
		if( pl.type.is_variable( pointer ) ) {
			thread.throw_error( pl.error.instantiation( atom.indicator ) );
			return null;
		} else if( !pl.type.is_empty_list( pointer ) ) {
			thread.throw_error( pl.error.type( "list", list, atom.indicator ) );
			return null;
		}
		return pairs;
	};

	var to_list = function( items ) {
		var list = new pl.type.Term( "[]", [] );
		for( var i = items.length - 1; i >= 0; i-- )
			list = new pl.type.Term( ".", [items[i], list] );
		return list;
	};

	var keys_of = function( pairs ) {
		return to_list( pairs.map( function( p ) { return p.args[0]; } ) );
	};

	var values_of = function( pairs ) {
		return to_list( pairs.map( function( p ) { return p.args[1]; } ) );
	};

	// Replace the goal by the conjunction of the unifications left = right
	var unify_all = function( thread, point, equations ) {
		var goal = equations[equations.length - 1];
		for( var i = equations.length - 2; i >= 0; i-- )
			goal = new pl.type.Term( ",", [equations[i], goal] );
		thread.prepend( [new pl.type.State( point.goal.replace( goal ), point.substitution, point )] );
	};

	var equation = function( left, right ) {
		return new pl.type.Term( "=", [left, right] );
	};

	var predicates = function() {

		return {

			// pairs_keys_values/3
			"pairs_keys_values/3": function( thread, point, atom ) {
				var pairs = atom.args[0], keys = atom.args[1], values = atom.args[2];
				if( pl.type.is_variable( pairs ) ) {
					if( !pl.type.is_instantiated_list( keys ) || !pl.type.is_instantiated_list( values ) ) {
						thread.throw_error( pl.error.instantiation( atom.indicator ) );
						return;
					}
					var ks = [], vs = [];
					for( var k = keys; k.indicator === "./2"; k = k.args[1] )
						ks.push( k.args[0] );
					for( var v = values; v.indicator === "./2"; v = v.args[1] )
						vs.push( v.args[0] );
					if( ks.length === vs.length )
						unify_all( thread, point, [equation( pairs, to_list( ks.map( function( key, i ) {
							return new pl.type.Term( "-", [key, vs[i]] );
						} ) ) )] );
				} else {
					var found = read_pairs( thread, atom, pairs );
					if( found !== null )
						unify_all( thread, point, [equation( keys, keys_of( found ) ), equation( values, values_of( found ) )] );
				}
			},

			// pairs_keys/2
			"pairs_keys/2": function( thread, point, atom ) {
				var found = read_pairs( thread, atom, atom.args[0] );
				if( found !== null )
					unify_all( thread, point, [equation( atom.args[1], keys_of( found ) )] );
			},

			// pairs_values/2
			"pairs_values/2": function( thread, point, atom ) {
				var found = read_pairs( thread, atom, atom.args[0] );
				if( found !== null )
					unify_all( thread, point, [equation( atom.args[1], values_of( found ) )] );
			},

			// transpose_pairs/2
			"transpose_pairs/2": function( thread, point, atom ) {
				var found = read_pairs( thread, atom, atom.args[0] );
				if( found !== null ) {
					var swapped = found.map( function( p ) { return new pl.type.Term( "-", [p.args[1], p.args[0]] ); } );
					swapped.sort( function( a, b ) { return pl.compare( a.args[0], b.args[0] ); } );
					unify_all( thread, point, [equation( atom.args[1], to_list( swapped ) )] );
				}
			},

			// group_pairs_by_key/2
			"group_pairs_by_key/2": function( thread, point, atom ) {
				var found = read_pairs( thread, atom, atom.args[0] );
				if( found !== null ) {
					var groups = [], current = null;
					found.forEach( function( p ) {
						if( current !== null && pl.compare( current.key, p.args[0] ) === 0 ) {
							current.values.push( p.args[1] );
						} else {
							current = { key: p.args[0], values: [p.args[1]] };
							groups.push( current );
						}
					} );
					unify_all( thread, point, [equation( atom.args[1], to_list( groups.map( function( g ) {
						return new pl.type.Term( "-", [g.key, to_list( g.values )] );
					} ) ) )] );
				}
			}

		};
	};

	var exports = ["pairs_keys_values/3", "pairs_keys/2", "pairs_values/2", "transpose_pairs/2", "group_pairs_by_key/2"];

	if( typeof module !== 'undefined' ) {
		module.exports = function( p ) {
			pl = p;
			new pl.type.Module( name, predicates(), exports );
		};
	} else {
		new pl.type.Module( name, predicates(), exports );
	}
})( pl );
